<script>
function selectPlanCard(card) {
    document.querySelectorAll('.plan-card').forEach(c => {
        c.classList.remove('border-brand-orange', 'bg-brand-orangeLight', 'ring-2', 'ring-brand-orange/20');
        c.classList.add('border-slate-100', 'bg-slate-50');
        c.querySelector('.check-icon').classList.remove('opacity-100');
    });

    card.classList.remove('border-slate-100', 'bg-slate-50');
    card.classList.add('border-brand-orange', 'bg-brand-orangeLight', 'ring-2', 'ring-brand-orange/20');
    card.querySelector('.check-icon').classList.add('opacity-100');

    document.getElementById('planSel').value = card.getAttribute('data-id');
    document.getElementById('planPrice').value = card.getAttribute('data-price');
    document.getElementById('planName').value = card.getAttribute('data-name');
}

function resetVerify() {
    document.getElementById('verifiedF').value = '0';
    document.getElementById('verifyCard').classList.add('hidden');
}

function verifySC() {
    const cid = document.getElementById('cableId').value;
    const sc = document.getElementById('scF').value;
    
    if(!sc) return Swal.fire('Notice', 'Enter smartcard number', 'info');
    
    const btn = document.getElementById('verifyBtn');
    const ogHtml = btn.innerHTML;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';
    btn.disabled = true;
    
    const fd = new FormData();
    fd.append('action', 'validate_smart');
    fd.append('csrf_token', document.getElementById('csrfF').value);
    fd.append('cable_id', cid);
    fd.append('smartcard', sc);
    
    fetch('', { method: 'POST', headers: {'X-Requested-With': 'XMLHttpRequest'}, body: fd })
    .then(async r => { const txt = await r.text(); try { return JSON.parse(txt); } catch(e) { console.error('Raw response:', txt); throw new Error(txt); } })
    .then(res => {
        btn.innerHTML = ogHtml;
        btn.disabled = false;
        
        if(res.success) {
            document.getElementById('verifiedF').value = '1';
            document.getElementById('vName').innerText = res.name;
            document.getElementById('verifyCard').classList.remove('hidden');
        } else {
            showAlert(res.message || 'Verification failed', 'Error');
            resetVerify();
        }
    })
    .catch(err => {
        btn.innerHTML = ogHtml;
        btn.disabled = false;
        Swal.fire('Notice', 'Network error verifying smartcard', 'info');
    });
}

function openConfirm() {
    const sc = document.getElementById('scF').value;
    const isV = document.getElementById('verifiedF').value;
    const planId = document.getElementById('planSel').value;
    
    if(!sc) return Swal.fire('Notice', 'Enter smartcard number', 'info');
    if(isV !== '1') return Swal.fire('Notice', 'Please verify smartcard first', 'info');
    if(!planId) return Swal.fire('Notice', 'Please select a bouquet', 'info');
    
    const prc = document.getElementById('planPrice').value;
    const bName = document.getElementById('planName').value;
    const name = document.getElementById('vName').innerText;
    const prov = '<?=$sel_prov?>';
    
    confirmTransaction({
        "Transaction": "Cable Subscription",
        "Provider": prov,
        "Bouquet": bName,
        "Smartcard": sc,
        "Name": name,
        "Amount": "₦" + Number(prc).toLocaleString()
    }, function(pin) {
        processPurchase(planId, sc, pin);
    });
}

function processPurchase(planId, sc, pin) {
    const btn = document.querySelector('button[onclick="openConfirm()"]');
    const ogHtml = btn.innerHTML;
    btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Processing...';
    btn.disabled = true;
    
    const cid = document.getElementById('cableId').value;
    
    const fd = new FormData();
    fd.append('action', 'pay');
    fd.append('csrf_token', document.getElementById('csrfF').value);
    fd.append('cable_id', cid);
    fd.append('plan_id', planId);
    fd.append('smartcard', sc);
    fd.append('pin', pin);
    
    fetch('', {
        method: 'POST',
        headers: { 'X-Requested-With': 'XMLHttpRequest' },
        body: fd
    })
    .then(async r => { const txt = await r.text(); try { return JSON.parse(txt); } catch(e) { console.error('Raw response:', txt); throw new Error(txt); } })
    .then(res => {
        if (res.ref) {
            window.location.href = '/user/receipt.php?ref=' + res.ref;
        } else {
            Swal.fire(res.success ? 'Success' : 'Notice', res.message, res.success ? 'success' : 'info');
            if (typeof btn !== 'undefined' && typeof ogHtml !== 'undefined') {
                btn.innerHTML = ogHtml;
                btn.disabled = false;
            }
        }
    })
    .catch(err => {
        console.error(err); Swal.fire('Server Error', err.message.substring(0, 200), 'error');
        btn.innerHTML = ogHtml;
        btn.disabled = false;
    });
}
</script>

